// @file ./agents/gpt-researcher.ts
import { defineAgent } from "niceeval/adapter";
import type { Agent, EvidenceCoverage } from "niceeval/adapter";

const evidenceCoverage = {
  events: { status: "partial", reason: "The WebSocket protocol exposes streamed report text but not a complete event stream." },
  actions: { status: "unavailable", reason: "The WebSocket protocol does not expose structured tool lifecycle events." },
  messages: { status: "complete" },
  usage: { status: "unavailable", reason: "The WebSocket protocol does not return token or cost usage." },
  status: { status: "complete" },
  data: { status: "unavailable", reason: "The WebSocket protocol does not return structured report data." },
} satisfies EvidenceCoverage;

type ServerEvent = {
  type?: string;
  content?: string;
  output?: unknown;
};

export function gptResearcher(options: { wsUrl: string }): Agent {
  return defineAgent({
    name: "gpt-researcher-websocket",
    evidenceCoverage,
    async send(input, ctx) {
      ctx.progress({ message: "Waiting for GPT Researcher report" });

      const result = await new Promise<{ report: string; error?: string }>((resolve, reject) => {
        const socket = new WebSocket(options.wsUrl);
        const reportChunks: string[] = [];

        const cleanup = () => {
          ctx.signal.removeEventListener("abort", onAbort);
          socket.close();
        };
        const onAbort = () => {
          cleanup();
          reject(ctx.signal.reason ?? new Error("Evaluation cancelled"));
        };

        ctx.signal.addEventListener("abort", onAbort, { once: true });
        socket.addEventListener("open", () => {
          socket.send(`start ${JSON.stringify({
            task: input.text,
            report_type: "research_report",
            report_source: "local",
            tone: "Objective",
            query_domains: [],
            mcp_enabled: false,
            mcp_strategy: "fast",
            mcp_configs: [],
          })}`);
        });
        socket.addEventListener("message", (event) => {
          let message: ServerEvent;
          try {
            message = JSON.parse(String(event.data)) as ServerEvent;
          } catch {
            cleanup();
            reject(new Error("GPT Researcher returned a non-JSON WebSocket frame"));
            return;
          }

          if (message.type === "report" && typeof message.output === "string") {
            reportChunks.push(message.output);
            return;
          }
          if (message.type === "error" || message.content === "error") {
            cleanup();
            resolve({ report: reportChunks.join(""), error: String(message.output ?? "GPT Researcher reported an error") });
            return;
          }
          if (message.type === "path") {
            cleanup();
            resolve({ report: reportChunks.join("") });
          }
        });
        socket.addEventListener("error", () => {
          cleanup();
          reject(new Error(`Could not connect to GPT Researcher at ${options.wsUrl}; start the backend first.`));
        });
        socket.addEventListener("close", () => {
          if (!ctx.signal.aborted && reportChunks.length === 0) {
            reject(new Error("GPT Researcher closed the WebSocket before returning a report"));
          }
        });
      });

      if (result.error) {
        return {
          status: "failed",
          events: [{ type: "error", message: result.error }],
        };
      }

      return {
        status: "completed",
        events: [{ type: "message", role: "assistant", text: result.report }],
      };
    },
  });
}

