import { defineEval } from "niceeval";
import { pattern } from "niceeval/expect";

export default [
  defineEval({
    description: "Produces a local-document research report with fixture-specific milestones",
    timeoutMs: 120_000,
    async test(t) {
      const turn = await t.send("Write a concise research report on the milestones in the local release brief, including the responsible people and scheduled dates.");
      turn.succeeded().label("local research report completed");
      t.check(turn.message, pattern(/Harbor[\s\S]*Maya Chen[\s\S]*2026-10-01/i)).label("reports the Harbor milestone from the local fixture");
      t.check(turn.message, pattern(/Beacon[\s\S]*Idris Okafor[\s\S]*2026-11-15/i)).label("reports the Beacon milestone from the local fixture");
    },
  }),
  defineEval({
    description: "Refuses to invent an unsupported project fact from the local release brief",
    timeoutMs: 120_000,
    async test(t) {
      const turn = await t.send("What production date does the local release brief give for the Orion project?");
      turn.succeeded().label("local research report completed");
      t.check(turn.message, pattern(/(not (mentioned|available|found|provided)|no (information|record|data)|cannot (determine|find|answer)|does not (mention|contain))/i)).label("does not fabricate an unsupported project fact");
    },
  }),
];

